package com.example

/**
 * Grade 10 Buddhism Syllabus Question Bank for Live Exam Hall.
 * Covers Terms 1, 2, and 3 with 60 distinct syllabus topic slots per term.
 * Permutes slots with coprime 7 so each paper presents all 60 syllabus points in unique sequence,
 * and provides distinct question variations across papers 1 to 30.
 */
object BuddhismGrade10QuestionBank {

  fun getQuestion(term: Int, paperIdx: Int, qNum: Int): MockExamQuestion {
    val cleanPaper = if (paperIdx in 1..30) paperIdx else 1
    val cleanQ = if (qNum in 1..60) qNum else 1
    val effectiveSlot = ((cleanQ - 1 + (cleanPaper - 1) * 7) % 60) + 1
    return when (term) {
      1 -> getTerm1Question(cleanPaper, cleanQ, effectiveSlot)
      2 -> getTerm2Question(cleanPaper, cleanQ, effectiveSlot)
      else -> getTerm3Question(cleanPaper, cleanQ, effectiveSlot)
    }
  }

  // ==========================================================================
  // GRADE 10 - TERM 1 (Slots 1 to 60)
  // ==========================================================================
  private fun getTerm1Question(paperIdx: Int, qNum: Int, slot: Int): MockExamQuestion {
    val v = paperIdx - 1
    val (topic, quad) = when (slot) {
      in 1..6 -> "බුදුරදුන්ගේ ඥාන ශක්තිය සහ බුද්ධ ගුණ" to run {
        val list = listOf(
          Quad("බුදුවරයෙකුට පමණක් පිහිටන අසමසම බල මහිමය හැඳින්වෙන්නේ කුමන නාමයෙන්ද?", listOf("දස බල ඥාන (Dasa Bala)", "චතුර්වේද", "පංච ඉන්ද්‍රිය", "අෂ්ටලෝක ධර්ම"), 1, "තථාගත බුදුරදුන් සතු අසමසම ඥාන ශක්තීන් දහය දස බල ඥාන ලෙස හැඳින්වේ."),
          Quad("කිසිදු බියකින් හෝ පැකිලීමකින් තොරව සත්‍යය ප්‍රකාශ කිරීමේ බුදුරදුන් සතු ශක්තිය කුමක්ද?", listOf("චතුර්වෛශාරද්‍ය ඥානය (Chatur Vaisharadya)", "දස පාරමිතා", "සතර සතිපට්ඨාන", "සතර ඍද්ධිපාද"), 1, "සව් කෙලෙසුන් නැසූ බව, සියලු ධර්මයන් අවබෝධ කළ බව ආදී සතර කරුණකදී විශාරදත්වයට පත්වීමයි."),
          Quad("බුදුරදුන් සතු පඤ්ච චක්ඛු (ඇස් පහ) අතර සියලු ධර්මයන් අවබෝධ කරගන්නා නුවණැස කුමක්ද?", listOf("ධම්ම චක්ඛු (දහම් ඇස)", "මංස චක්ඛු", "දිබ්බ චක්ඛු", "සමන්ත චක්ඛු"), 1, "සත්‍ය ධර්මය පිරිසිඳ දැකීමේ නුවණ ධම්ම චක්ඛු නම් වේ."),
          Quad("ලොව සියලු සත්වයන්ගේ චරිත ස්වභාවය හා ආශය අනුසය අවබෝධ කරගන්නා බුද්ධ ඥානය කුමක්ද?", listOf("ආසයානුසය ඥානය සහ ඉන්ද්‍රියපරෝපරියත්ත ඥානය", "දිබ්බසෝත ඥානය", "චේතෝපරිය ඥානය පමණක්", "පුබ්බේනිවාසානුස්සති ඥානය"), 1, "සත්වයන්ගේ ඉන්ද්‍රියන්ගේ මෝරා ඇති බව දැන ධර්මය දේශනා කිරීමට මෙම ඥාන උපකාරී වේ."),
          Quad("බුදුරදුන් සතු 'විජ්ජාචරණ සම්පන්න' ගුණයෙන් අදහස් වන අෂ්ට විද්‍යාවන්ට අයත් නොවන්නේ කුමක්ද?", listOf("අනාවරණ ඥානය", "විපස්සනා ඥානය", "මනෝමය ඉද්ධි ඥානය", "ආසවක්ඛය ඥානය"), 1, "අෂ්ට විද්‍යාවන්ට විපස්සනා, මනෝමය ඉද්ධි, ඉද්ධිවිධ, දිබ්බසෝත, චේතෝපරිය, පුබ්බේනිවාසානුස්සති, දිබ්බචක්ඛු හා ආසවක්ඛය අයත් වේ."),
          Quad("සකල ලෝකවාසී සත්වයන් කෙරෙහි බුදුරදුන් තුළ පැවති අසීමිත කරුණාව දැක්වෙන බුද්ධ ගුණය කුමක්ද?", listOf("මහා කරුණා සමාපත්ති ඥානය", "දස බල ඥානය", "අෂ්ට විද්‍යා", "අභිඤ්ඤා"), 1, "බුදුරදුන් දිනපතා අලුයම මහා කරුණා සමාපත්තියට සමවැදී පිහිට විය යුතු සත්වයන් සොයා බැලූහ.")
        )
        list[(slot - 1 + v).mod(list.size)]
      }
      in 7..12 -> "චතුරාර්ය සත්‍ය ධර්මය" to run {
        val list = listOf(
          Quad("බුදුදහමේ පදනම වන චතුරාර්ය සත්‍ය ධර්මයන්ගේ දෙවන සත්‍යය වන දුක්ඛ සමුදය සත්‍යයෙන් දැක්වෙන්නේ කුමක්ද?", listOf("දුක හටගැනීමට හේතුව වන තණ්හාව (තෘෂ්ණාව)", "දුකෙන් මිදීම", "දුක නැති කිරීමේ මග", "දුකෙහි ස්වභාවය"), 1, "කාම තණ්හා, භව තණ්හා, විභව තණ්හා යන ත්‍රිවිධ තෘෂ්ණාව සියලු දුක්වලට හේතුවයි."),
          Quad("චතුරාර්ය සත්‍යයේ තෙවන සත්‍යය වන 'දුක්ඛ නිරෝධ සත්‍යය' යන්නෙන් අදහස් වන්නේ කුමක්ද?", listOf("තණ්හාව මුළුමනින්ම ප්‍රහාණය කිරීමෙන් ලබන නිර්වාණ සුවය", "මරණයට පත්වීම", "නින්දට යාම", "භාවනා කිරීම පමණක්"), 1, "දුක මුළුමනින්ම නැති කිරීම හෙවත් නිර්වාණය දුක්ඛ නිරෝධ සත්‍යයයි."),
          Quad("දුක්ඛ නිරෝධ ගාමිණී පටිපදා ආර්ය සත්‍යය හෙවත් දුක නැති කිරීමේ මාර්ගය කුමක්ද?", listOf("ආර්ය අෂ්ටාංගික මාර්ගය (මධ්‍යමා ප්‍රතිපදාව)", "සතර සතිපට්ඨානය පමණක්", "දස කුසල් පමණක්", "දස පාරමිතා පමණක්"), 1, "සම්මා දිට්ඨි ආදී අංග අටකින් සමන්විත ආර්ය අෂ්ටාංගික මාර්ගය නිර්වාණ මාර්ගයයි."),
          Quad("ආර්ය අෂ්ටාංගික මාර්ගයේ අංග අට ත්‍රිශික්ෂාවට බෙදීමේදී 'ප්‍රඥා' ශික්ෂාවට අයත් අංග දෙක මොනවාද?", listOf("සම්මා දිට්ඨි සහ සම්මා සංකප්ප", "සම්මා වාචා සහ සම්මා කම්මන්ත", "සම්මා වායාම සහ සම්මා සති", "සම්මා ආජීව සහ සම්මා සමාධි"), 1, "සම්මා දිට්ඨි (නිවැරදි දැකීම) සහ සම්මා සංකප්ප (නිවැරදි කල්පනාව) ප්‍රඥා ශික්ෂාවට අයත් වේ."),
          Quad("ආර්ය අෂ්ටාංගික මාර්ගයේ 'සීල' ශික්ෂාවට අයත් වන අංග තුන මොනවාද?", listOf("සම්මා වාචා, සම්මා කම්මන්ත, සම්මා ආජීව", "සම්මා දිට්ඨි, සම්මා සංකප්ප, සම්මා වායාම", "සම්මා සති, සම්මා සමාධි, සම්මා දිට්ඨි", "සම්මා වායාම, සම්මා සති, සම්මා සමාධි"), 1, "යහපත් වචනය, යහපත් ක්‍රියාව සහ යහපත් ජීවිකාව සීල ශික්ෂාවයි."),
